from django.db import migrations, models
from django.utils.text import slugify


def backfill_service_slugs(apps, schema_editor):
    """Existing services have no slug; a blank one would break uniqueness."""
    Service = apps.get_model("core", "Service")
    taken = set()
    for service in Service.objects.order_by("pk"):
        base = slugify(service.title)[:80] or "service"
        slug, suffix = base, 2
        while slug in taken:
            slug = f"{base}-{suffix}"
            suffix += 1
        taken.add(slug)
        service.slug = slug
        service.save(update_fields=["slug"])


